        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans specify the measured tail frequency, uncertainty, classification ranges, timing comparability and treatment of incomplete trials."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C001_RELATION",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to warrant this definition of the investigated property."
    }
  },
  "rationale": "The operation and signal directly operationalize the probability of exceeding one hour under comparable workloads. This licenses the claim within its definitional scope; the claim does not assert that an increase has actually been established.",
  "uncertainty": "Sampling uncertainty affects revision classification, but does not undermine the stated definition of the target property.",
